from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
file=ROOT/'js/app.js'
s=file.read_text()
s=s.replace("['podcasts','◈','Podcasts'],['reading'", "['podcasts','◈','Podcasts'],['authentic','🎧','Real Voices · VOA'],['reading'")
s=s.replace("memoryPhase:'learn'", "authenticId:null,authenticAnswers:{},authenticTranscript:false,memoryPhase:'learn'")
s=s.replace("P.memoryCues??={};", "P.memoryCues??={};\nP.authenticLessons??={};")
pos=s.index("function listening(){")
fn=r'''function authenticLibrary(){const lessons=data.authentic||[];return `${section('Real Voices · VOA','Gerçek insan sesi ve VOA’nın yayımladığı transkriptlerle dinleme. Çevrimiçi bağlantı gerektirir.','HUMAN SPEECH • ATTRIBUTED')}
<div class="callout"><b>Doğal Amerikan İngilizcesi — çevrimiçi pilot</b><p>Bu bölümün sesleri VOA Learning English’in kendi kayıtlarına bağlanır. Transkriptler VOA’nın yayımladığı metinlerdir, otomatik ASR çıktısı değildir. Ses–metin zaman eşlemesi henüz yapılmadı. İçerikler bu sürümde çevrimdışı dinlenemez.</p><p class="footnote">Kaynak: <a href="https://learningenglish.voanews.com/p/6861.html" target="_blank" rel="noopener noreferrer">VOA kullanım izni ve atıf koşulları</a>. Üçüncü taraf ajans kayıtları kullanılmaz.</p></div>
<div class="grid">${lessons.map(x=>`<div class="panel episode-card span-4"><div class="cover">♫</div><div class="row"><span class="tag green">${E(x.level)}</span><span class="tag">${x.minutes.toFixed(1)} dk</span><span class="tag">Gerçek ses</span></div><h3 style="margin-top:11px">${E(x.title)}</h3><p>${E(x.topic)} · ${x.questions.length} özgün soru</p><p class="mini">${(P.authenticLessons||{})[x.id]?'✓ Önceki sonuç: '+P.authenticLessons[x.id].correct+'/'+P.authenticLessons[x.id].total:'Henüz tamamlanmadı'}</p>${button('▶ Gerçek konuşmayı aç','authenticOpen','small primary',`data-id="${E(x.id)}"`)}</div>`).join('')}</div>`;}
function authenticDetail(){const x=(data.authentic||[]).find(x=>x.id===ui.authenticId);if(!x)return authenticLibrary();const last=(P.authenticLessons||{})[x.id];return `<div class="row" style="margin-bottom:15px">${button('← Real Voices','authenticBack','small ghost')}<span class="tag green">${E(x.level)}</span><span class="tag">${E(x.topic)}</span></div>${section(x.title,'Önce transkript kapalıyken dinle, ardından soruları cevapla.','REAL HUMAN VOICES · VOA')}
<div class="panel"><div class="row between"><b>▶ Voice of America · ${x.minutes.toFixed(1)} dk</b><span class="tag">ONLINE MP3 · HUMAN</span></div><audio id="media" aria-label="VOA doğal İngilizce dinleme" controls preload="none" src="${E(x.audioUrl)}"></audio><div class="row"><label for="speed">Hız</label><select id="speed" class="search" style="width:auto" data-field="speed">${[.75,.9,1,1.15,1.3].map(v=>`<option ${ui.speed===v?'selected':''} value="${v}">${v}×</option>`).join('')}</select></div><p class="mini">Bu ses VOA sunucusundan internet üzerinden açılır. Oynatılmazsa <a href="${E(x.sourceUrl)}" target="_blank" rel="noopener noreferrer">orijinal kaydı VOA üzerinde aç</a>. İnternet bağlantısı olmadan çalışmaz.</p></div>
<div class="grid" style="margin-top:16px"><div class="span-7 panel"><div class="row between"><h2>Kaynak transkripti</h2>${button(ui.authenticTranscript?'Metni gizle':'Metni göster','authenticToggleTranscript','small soft')}</div><p class="mini">Metin, VOA tarafından yayımlanan transkripttir. Saniye bazında ses eşleşmesi henüz doğrulanmadı.</p><div id="authenticTranscript" ${ui.authenticTranscript?'':'hidden'} class="transcript">${x.turns.map(t=>`<div class="turn" style="cursor:default"><strong>${E(t.speaker)}</strong><p>${E(t.text)}</p></div>`).join('')}</div>${ui.authenticTranscript?'':'<p id="authenticTranscriptNote" class="mini">İlk dinlemede metin gizlidir.</p>'}</div>
<div class="span-5 panel"><div class="small-label">LISTEN AND UNDERSTAND</div><h2>Özgün anlama soruları</h2><p class="mini">Sorular bu projede hazırlandı; VOA’nın özgün quizini kopyalamıyor.</p>${x.questions.map((q,i)=>`<div class="test-question" data-auth-q="${i}"><b>${i+1}. ${E(q.question)}</b><div class="choice-list">${q.options.map((o,j)=>`<button class="choice ${ui.authenticAnswers[i]===j?'correct':''}" data-act="authenticAnswer" data-q="${i}" data-choice="${j}" ${ui.authenticAnswers[i]!==undefined?'disabled':''}>${E(o)}</button>`).join('')}</div><div class="auth-feedback">${ui.authenticAnswers[i]===undefined?'':`<div class="notice ${ui.authenticAnswers[i]===q.answer?'ok':'warn'}">${ui.authenticAnswers[i]===q.answer?'✓ Doğru':'✕ Tekrar çalış'} · ${E(q.explanation)}</div>`}</div></div>`).join('')}
${button('Dinlemeyi tamamla','authenticFinish','primary')}${last?`<div class="notice ok">Önceki kayıt: ${last.correct}/${last.total} · Bu skor tek başına CEFR seviyesi değildir.</div>`:''}</div></div><div class="panel" style="margin-top:16px"><h3>Kelime ve phrasal verb bağlantıları</h3><p>${x.focus.map(E).join(' · ')}</p><p class="mini">Bu ifadeleri dinlerken tanıyıp kendi cümlende kullanmaya çalış. Ayrıntılı alıştırmalar sonraki kalite aşamasında.</p><p class="footnote">Atıf: <a href="${E(x.sourceUrl)}" target="_blank" rel="noopener noreferrer">${E(x.attribution)} — ${E(x.sourceSeries)}</a></p></div>`;}
'''
s=s[:pos]+fn+s[pos:]
s=s.replace("const pages={home,listening:", "const pages={home,authentic:()=>ui.authenticId?authenticDetail():authenticLibrary(),listening:")
s=s.replace("const keys=['vocabulary','phrasals','episodes','readings','drills','grammar','rapid','focus'];", "const keys=['vocabulary','phrasals','episodes','readings','drills','grammar','rapid','focus','authentic'];")
s=s.replace("k==='focus'?'fluency-focus':k", "k==='focus'?'fluency-focus':k==='authentic'?'authentic-listening':k")
s=s.replace("case 'goto': ui.episode=null;", "case 'goto': ui.authenticId=null;ui.authenticAnswers={};ui.authenticTranscript=false;ui.episode=null;")
position=s.index(" case 'openEpisode':")
cases=r''' case 'authenticOpen':stopAudio();ui.authenticId=ds.id;ui.authenticAnswers={};ui.authenticTranscript=false;ui.view='authentic';ui.speed=1;location.hash='/authentic';render();scrollTo(0,0);break;
 case 'authenticBack':stopAudio();ui.authenticId=null;ui.authenticAnswers={};ui.authenticTranscript=false;render();break;
 case 'authenticToggleTranscript':{ui.authenticTranscript=!ui.authenticTranscript;const t=document.querySelector('#authenticTranscript');if(t)t.hidden=!ui.authenticTranscript;const note=document.querySelector('#authenticTranscriptNote');if(note)note.hidden=ui.authenticTranscript;buttonEl.textContent=ui.authenticTranscript?'Metni gizle':'Metni göster';break;}
 case 'authenticAnswer':{const lesson=(data.authentic||[]).find(x=>x.id===ui.authenticId),i=Number(ds.q),choice=Number(ds.choice);if(!lesson||ui.authenticAnswers[i]!==undefined||!lesson.questions[i]||!Number.isInteger(choice))break;const q=lesson.questions[i];if(choice<0||choice>=q.options.length)break;ui.authenticAnswers[i]=choice;const wrap=document.querySelector(`[data-auth-q="${i}"]`);if(wrap){wrap.querySelectorAll('button.choice').forEach((b,j)=>{b.disabled=true;if(j===choice)b.classList.add('correct');});const f=wrap.querySelector('.auth-feedback');if(f)f.innerHTML=`<div class="notice ${choice===q.answer?'ok':'warn'}">${choice===q.answer?'✓ Doğru':'✕ Tekrar çalış'} · ${E(q.explanation)}</div>`;}break;}
 case 'authenticFinish':{const lesson=(data.authentic||[]).find(x=>x.id===ui.authenticId);if(!lesson)break;const n=lesson.questions.length;if(Object.keys(ui.authenticAnswers).length!==n){notify(`Önce ${n} sorunun tamamını cevapla.`);break;}const correct=lesson.questions.filter((q,i)=>ui.authenticAnswers[i]===q.answer).length;P.authenticLessons[lesson.id]={correct,total:n,completedAt:Date.now()};event('authentic-listening');notify(`Gerçek konuşma tamamlandı: ${correct}/${n}`);break;}
'''
s=s[:position]+cases+s[position:]
s=s.replace('function listening(){',"function listening(){")
s=s.replace("<div class=\"headline\"><h2>Sound & Sentence Labs", "<div class=\"panel\" style=\"margin-top:18px\"><h2>Gerçek Amerikan İngilizcesi dinle</h2><p>VOA kaynaklı 3 dinleme, yayımlanmış transkript ve 16 özgün soru. Sesleri açmak için internet gerekir.</p>${link('authentic','Gerçek sesli dersleri aç →')}</div><div class=\"headline\"><h2>Sound & Sentence Labs")
file.write_text(s)
sw=ROOT/'sw.js';txt=sw.read_text();txt=txt.replace("'./data/grammar.json'];", "'./data/grammar.json','./data/authentic-listening.json'];");txt=txt.replace('ael-dev-20261028-spoken-quality-91-1','ael-dev-20261028-voa-pilot-1');sw.write_text(txt)
